#!/usr/bin/env python3
"""Writes internal/assistant/files/mimetypes_table.go from CPython's built-in mimetypes tables (a MimeTypes() instance: no host mime.types; mimetypes.init(files=[]) still reads the host's knownfiles)."""
import mimetypes
import sys
from pathlib import Path

db = mimetypes.MimeTypes()


def literal(name, table):
    rows = "".join(f'\t{{"{k}", "{v}"}},\n' for k, v in sorted(table.items()))
    return f"var {name} = pairs([][2]string{{\n{rows}}})\n"


def build():
    return (
        "// Code generated by tools/golden/gen_mimetypes.py from Python "
        f"{sys.version_info.major}.{sys.version_info.minor} mimetypes; DO NOT EDIT.\n\n"
        "package files\n\n"
        + literal("mimeTypes", db.types_map[True])
        + "\n"
        + literal("mimeSuffixes", db.suffix_map)
        + "\n"
        + literal("mimeEncodings", db.encodings_map)
    )


if __name__ == "__main__":
    target = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parents[2] / "internal/assistant/files/mimetypes_table.go"
    target.write_text(build(), encoding="utf-8")
